def IFFlexToolkit_LoadCollection():
    import os
    from recurdyn import FFlex
    global model_document
    global model

    szFilename1 = os.getcwd()  # Full path of current ProcessNet dll
    szFilename1 += "\\..\\..\\TestModel\\FFlex\\FFlexLoadCollection\\FFlexLoadCollection_V7R5.rdyn"
    model_document = application.OpenModelDocument(szFilename1)

    oldName = "FFlexBody1"
    newName = "FFlexBody2"

    model = model_document.Model

    fflexToolkit = model.FFlexToolkit
    if fflexToolkit is not None:
        fflexToolkit = FFlex.IFFlexToolkit(fflexToolkit)

    fflexLoads = FFlex.IFFlexLoadCollection(fflexToolkit.FFlexLoadCollection)

    newBody = model.GetEntity(newName)
    if newBody is not None:
        newBody = FFlex.IFFlexBody(newBody)

    for n in range(fflexLoads.Count):
        if isinstance(fflexLoads(n), FFlex.IFFlexLoadConcentrated):
            thisLoad = fflexLoads(n)
            if thisLoad is not None:
                thisLoad = FFlex.IFFlexLoadConcentrated(thisLoad)
            if (thisLoad.NodeSet.FullName.Contains(oldName)):
                nodeSet = newBody.GetEntity(thisLoad.NodeSet.Name)
                if nodeSet is not None:
                    nodeSet = FFlex.IFFlexNodeSet(nodeSet)
                thisLoad.NodeSet = nodeSet
        elif isinstance(fflexLoads(n), FFlex.IFFlexLoadPressure):
            thisLoad = fflexLoads(n)
            if thisLoad is not None:
                thisLoad = FFlex.IFFlexLoadPressure(thisLoad)
            if (thisLoad.PatchSet.FullName.Contains(oldName)):
                patchSet = newBody.GetEntity(thisLoad.PatchSet.Name)
                if patchSet is not None:
                    patchSet = FFlex.IFFlexPatchSet(patchSet)
                thisLoad.PatchSet = patchSet
